// Collect last week's emails from both inboxes and keep only the ones a person might expect a reply to.
// Drops automated senders, mailing lists and the owner's own addresses, keeps the latest message per thread,
// strips quoted text and trims bodies so each AI call stays small and cheap.
const s = $('Settings').first().json;
const mine = [s.personal_email, s.work_email].map(e => (e || '').toLowerCase());
const automated = /(no-?reply|do-?not-?reply|notifications?@|mailer-daemon|newsletter|updates?@|info@|news@|support@|billing@|receipts?@|security@|alerts?@|accounts?@|verify@|hello@|team@|marketing@)/i;
const automatedSubject = /(new (login|sign-?in)|security alert|verification code|verify your|password reset|reset your password|your (receipt|order|invoice)|order confirm|payment (received|confirm)|one-?time (code|password)|OTP|kode verifikasi)/i;
const safe = name => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };

const inboxes = [
  { account: 'Personal', messages: safe('Gmail: Get Personal Inbox') },
  { account: 'Work', messages: safe('Gmail: Get Work Inbox') },
];

function cleanBody(text) {
  const kept = [];
  for (const line of (text || '').split('\n')) {
    const t = line.trim();
    if (/^On .+ wrote:$/i.test(t) || /^Pada .+ menulis:$/i.test(t)) break;
    if (t.startsWith('>')) continue;
    kept.push(line);
  }
  return kept.join('\n').replace(/\n{3,}/g, '\n\n').trim().slice(0, 3000);
}

const latest = {};
const seenIds = new Set();
for (const { account, messages } of inboxes) {
  for (const m of messages) {
    if (!m.id || seenIds.has(m.id)) continue;
    seenIds.add(m.id);
    const fromAddress = (m.from?.value?.[0]?.address || '').toLowerCase();
    const headers = m.headers || {};
    if (!fromAddress || mine.includes(fromAddress)) continue;
    if (automated.test(fromAddress) || automatedSubject.test(m.subject || '')) continue;
    if (headers['list-unsubscribe'] || headers['list-id']) continue;
    const key = account + ':' + m.threadId;
    if (!latest[key] || new Date(m.date) > new Date(latest[key].date)) latest[key] = { ...m, account };
  }
}

return Object.values(latest).map(m => ({
  json: {
    account: m.account,
    messageId: m.id,
    threadId: m.threadId,
    fromName: m.from?.value?.[0]?.name || '',
    fromAddress: (m.from?.value?.[0]?.address || '').toLowerCase(),
    subject: m.subject || '(no subject)',
    date: m.date,
    body: cleanBody(m.text || ''),
  }
}));

