      "type": "string",
      "enum": [
        "high",
        "normal",
        "low"
      ]
    },
    "reason": {
      "type": "string",
      "description": "One short sentence explaining the decision"
    },
    "language": {
      "type": "string",
      "description": "Language of the email, e.g. English or Indonesian"
    },
    "reply": {
      "type": "string",
      "description": "Reply body written as the owner, empty when needs_reply is false"
    }
  },
  "required": [
    "needs_reply",
    "priority",
    "reason",
    "language",
    "reply"
  ]
}

