// Runs on every execution, after the draft branch, so the owner always gets a report.
const safe = name => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const personal = safe('Gmail: Get Personal Inbox').filter(m => m.id);
const personalIds = new Set(personal.map(m => m.id));
const work = safe('Gmail: Get Work Inbox').filter(m => m.id && !personalIds.has(m.id));
const workSkipped = work.length === 0;
const fetched = [...personal, ...work];
const emails = safe('Keep Emails From People');
const triage = safe('Triage and Draft Reply').map(t => t.output || {});
const drafts = [...safe('Gmail: Draft Reply (Personal)'), ...safe('Gmail: Draft Reply (Work)')];
const days = $('Settings').first().json.days_back;

const rows = emails.map((e, idx) => ({ ...e, ...(triage[idx] || {}) }));
const needs = rows.filter(r => r.needs_reply && r.reply);
const noReply = rows.filter(r => !(r.needs_reply && r.reply));
const failed = drafts.filter(d => d.error).length;
const order = { high: 0, normal: 1, low: 2 };
needs.sort((a, b) => (order[a.priority] ?? 1) - (order[b.priority] ?? 1));

const esc = s => String(s || '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const line = (r, tag = '') => `<li>${tag}<b>${esc(r.account)}</b> · ${esc(r.fromName || r.fromAddress)}: <b>${esc(r.subject)}</b><br><i>${esc(r.reason || 'not checked')}</i></li>`;

const html = `
<p><b>${needs.length} reply draft${needs.length === 1 ? '' : 's'} ready.</b> Each draft is saved in the Drafts folder of the inbox the email arrived in. Check anything in [square brackets] before sending.</p>
${needs.length ? `<ol>${needs.map(r => line(r, `[${esc(r.priority)}] `)).join('')}</ol>` : '<p>Nothing needed a reply this time.</p>'}
<p><b>Read but no reply needed (${noReply.length}):</b></p>
${noReply.length ? `<ul>${noReply.map(r => line(r)).join('')}</ul>` : '<p>None.</p>'}
<p style="color:#666">Last ${days} days across Personal and Work: ${fetched.length} emails fetched, ${fetched.length - emails.length} skipped as automated or newsletters, ${emails.length} read by the AI. Drafts that failed to save: ${failed}.${workSkipped ? ' <b>The Work inbox was not read (its Gmail login is not connected yet, or it had no new mail).</b>' : ''}</p>`;

return [{ json: { subject: `Inbox check: ${needs.length} reply draft${needs.length === 1 ? '' : 's'} ready`, html } }];
